import { NextResponse } from "next/server"
import {
  API_ACCEPTED_FORMATS,
  API_MAX_FILES,
  API_MAX_FILE_SIZE_MB,
  UPLOAD_FIELD_NAME,
} from "@/constants/upload-api.constants"
import {
  validateServerFile,
  validateServerUploadBatch,
} from "@/lib/server/upload-validation"
import { saveUploadedFiles } from "@/lib/server/upload-storage"

export async function POST(request: Request) {
  try {
    const formData = await request.formData()
    const files = formData
      .getAll(UPLOAD_FIELD_NAME)
      .filter((entry): entry is File => entry instanceof File)

    const batchResult = validateServerUploadBatch(files, {
      maxSizeMB: API_MAX_FILE_SIZE_MB,
      maxFiles: API_MAX_FILES,
      acceptedFormats: API_ACCEPTED_FORMATS,
    })

    if (!batchResult.isValid) {
      return NextResponse.json(
        { error: batchResult.errorMessage },
        { status: 400 },
      )
    }

    for (const file of files) {
      const fileResult = await validateServerFile(file, {
        maxSizeMB: API_MAX_FILE_SIZE_MB,
        acceptedFormats: API_ACCEPTED_FORMATS,
      })

      if (!fileResult.isValid) {
        const status = fileResult.errorMessage?.includes("grande")
          ? 413
          : 415
        return NextResponse.json(
          { error: fileResult.errorMessage },
          { status },
        )
      }
    }

    const uploadedFiles = await saveUploadedFiles(files)

    return NextResponse.json(
      {
        message: `Upload realizado com sucesso! ${uploadedFiles.length} arquivo(s) guardado(s).`,
        files: uploadedFiles,
      },
      { status: 201 },
    )
  } catch (error) {
    console.error("Erro na API de upload:", error)
    return NextResponse.json(
      { error: "Erro interno no servidor ao processar o upload." },
      { status: 500 },
    )
  }
}

import {
  UPLOAD_API_PATH,
  UPLOAD_FIELD_NAME,
} from "@/constants/upload-api.constants"

export interface UploadedFileMeta {
  name: string
  size: number
  type: string
  url: string
  storedAs?: string
}

export interface UploadApiResponse {
  message: string
  files: UploadedFileMeta[]
}

export interface UploadApiError {
  error: string
}

/**
 * Envia ficheiros para a API de upload do Next.js
 */
export async function uploadDocuments(
  files: File[],
  options?: {
    fieldName?: string
    endpoint?: string
  },
): Promise<UploadApiResponse> {
  const fieldName = options?.fieldName ?? UPLOAD_FIELD_NAME
  const endpoint = options?.endpoint ?? UPLOAD_API_PATH

  const formData = new FormData()
  files.forEach((file) => {
    formData.append(fieldName, file)
  })

  const response = await fetch(endpoint, {
    method: "POST",
    body: formData,
  })

  const result = (await response.json()) as UploadApiResponse & UploadApiError

  if (!response.ok) {
    throw new Error(result.error ?? "Falha ao enviar os arquivos.")
  }

  return result
}

import type { SupportedFileFormat } from "@/types/file-upload.types"
import type { FileValidationResult } from "@/types/file-upload.types"
import { getFileExtension } from "@/lib/file-validation"
import { sniffMimeType, isMimeAllowedForFormats } from "@/lib/file-signatures"
import { getAllowedMimeTypes } from "@/lib/file-mime-types"
import {
  BYTES_PER_MB,
  VALIDATION_ERRORS,
} from "@/constants/file-upload.constants"

export interface ServerUploadOptions {
  maxSizeMB: number
  maxFiles: number
  acceptedFormats: SupportedFileFormat[]
}

export function validateServerUploadBatch(
  files: File[],
  options: ServerUploadOptions,
): FileValidationResult {
  if (files.length === 0) {
    return {
      isValid: false,
      errorMessage: "Nenhum arquivo foi enviado.",
    }
  }

  if (files.length > options.maxFiles) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.TOO_MANY_FILES(options.maxFiles),
    }
  }

  return { isValid: true, errorMessage: null }
}

export async function validateServerFile(
  file: File,
  options: Pick<ServerUploadOptions, "maxSizeMB" | "acceptedFormats">,
): Promise<FileValidationResult> {
  const extension = getFileExtension(file.name)
  const normalizedFormats = options.acceptedFormats.map((f) =>
    f.toUpperCase(),
  )

  if (!extension || !normalizedFormats.includes(extension)) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.UNSUPPORTED_FORMAT(
        options.acceptedFormats,
      ),
    }
  }

  const maxSizeBytes = options.maxSizeMB * BYTES_PER_MB
  if (file.size > maxSizeBytes) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.FILE_TOO_LARGE(options.maxSizeMB),
    }
  }

  const header = new Uint8Array(await file.slice(0, 12).arrayBuffer())
  const sniffed = sniffMimeType(header)

  if (!sniffed) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.INVALID_MIME(options.acceptedFormats),
    }
  }

  if (!isMimeAllowedForFormats(sniffed, options.acceptedFormats)) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.INVALID_MIME(options.acceptedFormats),
    }
  }

  const allowedMimes = getAllowedMimeTypes(options.acceptedFormats)
  if (file.type && !allowedMimes.includes(file.type)) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.INVALID_MIME(options.acceptedFormats),
    }
  }

  if (file.type && file.type !== sniffed) {
    return {
      isValid: false,
      errorMessage: VALIDATION_ERRORS.INVALID_MIME(options.acceptedFormats),
    }
  }

  return { isValid: true, errorMessage: null }
}

import { mkdir, writeFile } from "fs/promises"
import path from "path"

const UPLOAD_DIR = path.join(process.cwd(), "public", "uploads")

function sanitizeFileName(name: string): string {
  return name.replace(/[^a-zA-Z0-9._-]/g, "_")
}

export interface SavedUploadFile {
  name: string
  size: number
  type: string
  url: string
  storedAs: string
}

export async function saveUploadedFile(file: File): Promise<SavedUploadFile> {
  await mkdir(UPLOAD_DIR, { recursive: true })

  const storedAs = `${Date.now()}-${sanitizeFileName(file.name)}`
  const filePath = path.join(UPLOAD_DIR, storedAs)
  const buffer = Buffer.from(await file.arrayBuffer())

  await writeFile(filePath, buffer)

  return {
    name: file.name,
    size: file.size,
    type: file.type || "application/octet-stream",
    url: `/uploads/${storedAs}`,
    storedAs,
  }
}

export async function saveUploadedFiles(
  files: File[],
): Promise<SavedUploadFile[]> {
  return Promise.all(files.map((file) => saveUploadedFile(file)))
}
